import re


class JasonPacketFinder(object):

    @staticmethod
    def find_beg(inp, start=0):
        """
        Finds beggining of json packet by searching for "_index" key and than returning backwards for opening bracket. Returns cur position of
        opening bracket in string.
        :param inp:
        :param start:
        :return:
        """
        index_ind = inp.find('"_index"', start)
        opening_bracket = inp.rfind("{", start, index_ind)
        return opening_bracket

    @staticmethod
    def find_packet(inp):
        """
        Returns json packets by searching for beginning of the packet in string and than tries to reach its end by counting { or } brackets.
        The sum of the brackets == 0 => whole packet is complete. Returns tuple (whole_packet_string, cursor_position_after_last_found_packet)
        :param inp:
        :return:
        """
        cur_pos = JasonPacketFinder.find_beg(inp)
        bracket_sum = 0
        for match in re.finditer('(\{|\})', inp):
            if match.group(1) == '{':
                bracket_sum += 1
            else:
                bracket_sum -= 1
            if bracket_sum == 0:
                end = match.end()
                yield inp[cur_pos:end], end
                cur_pos = JasonPacketFinder.find_beg(inp, end)
